body.script:
(function () {
  var shell = document.querySelector('.ar-shell');
  var form = document.getElementById('ar-action-form');
  var idsInput = document.getElementById('ar-player-ids');
  if (!shell || !form || !idsInput) return;

  var openUrl = shell.getAttribute('data-open-url');
  var completeUrl = shell.getAttribute('data-complete-url');
  var markUnsoldUrl = shell.getAttribute('data-mark-unsold-url');
  var toastEl = document.getElementById('ar-toast');
  var modalEl = document.getElementById('ar-modal');
  var modalCard = document.getElementById('ar-modal-card');
  var modalIcon = document.getElementById('ar-modal-icon');
  var modalTitle = document.getElementById('ar-modal-title');
  var modalMsg = document.getElementById('ar-modal-msg');
  var modalCancel = document.getElementById('ar-modal-cancel');
  var modalOk = document.getElementById('ar-modal-ok');
  var busy = false;
  var modalResolver = null;

  function toast(msg) {
    if (!toastEl) return;
    toastEl.textContent = msg;
    toastEl.classList.add('show');
    clearTimeout(toastEl._t);
    toastEl._t = setTimeout(function () { toastEl.classList.remove('show'); }, 2800);
  }

  function closeModal(result) {
    if (!modalEl) return;
    modalEl.classList.remove('show');
    modalEl.setAttribute('aria-hidden', 'true');
    var resolve = modalResolver;
    modalResolver = null;
    if (resolve) resolve(!!result);
  }

  function arConfirm(opts) {
    opts = opts || {};
    return new Promise(function (resolve) {
      if (!modalEl) { resolve(window.confirm(opts.message || 'Continue?')); return; }
      modalResolver = resolve;
      modalCard.classList.remove('is-danger', 'is-ok');
      if (opts.danger) modalCard.classList.add('is-danger');
      else modalCard.classList.add('is-ok');
      modalIcon.textContent = opts.icon || (opts.danger ? '🏁' : '🎯');
      modalTitle.textContent = opts.title || 'Confirm';
      modalMsg.innerHTML = opts.message || '';
      modalOk.textContent = opts.confirmLabel || 'Confirm';
      modalCancel.textContent = opts.cancelLabel || 'Cancel';
      modalOk.className = 'ar-btn ' + (opts.danger ? 'ar-btn-danger' : 'ar-btn-primary');
      modalEl.classList.add('show');
      modalEl.setAttribute('aria-hidden', 'false');
      setTimeout(function () { modalOk.focus(); }, 30);
    });
  }

  modalCancel.addEventListener('click', function () { closeModal(false); });
  modalOk.addEventListener('click', function () { closeModal(true); });
  modalEl.addEventListener('click', function (ev) {
    if (ev.target === modalEl) closeModal(false);
  });
  document.addEventListener('keydown', function (ev) {
    if (!modalEl.classList.contains('show')) return;
    if (ev.key === 'Escape') closeModal(false);
    if (ev.key === 'Enter') closeModal(true);
  });

  function poolName() {
    return shell.getAttribute('data-pool') || 'draft';
  }
  function resolveName(name) {
    return name === 'pool' ? poolName() : name;
  }
  function panel(name) {
    return document.querySelector('.ar-panel[data-panel="' + resolveName(name) + '"]');
  }
  function esc(value) {
    return String(value || '').replace(/[&<>"']/g, function (ch) {
      return {'&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;'}[ch];
    });
  }
  function activeTier(name) {
    var key = name === 'pool' ? 'pool' : resolveName(name);
    var wrap = document.querySelector('[data-tier-filters="' + key + '"]');
    if (!wrap) return [];
    return Array.prototype.map.call(
      wrap.querySelectorAll('.ar-tier-chip.is-active[data-tier-id]'),
      function (btn) { return String(btn.getAttribute('data-tier-id') || ''); }
    ).filter(function (id) { return id !== ''; });
  }
  var pageState = {};

  function pageSize() {
    if (window.matchMedia('(min-width: 900px)').matches) return 12;
    if (window.matchMedia('(min-width: 640px)').matches) return 10;
    return 8;
  }

  function ensurePager(p) {
    if (!p.querySelector('.ar-list') || p.querySelector('.ar-pager')) return;
    function make() {
      var nav = document.createElement('nav');
      nav.className = 'ar-pager';
      nav.setAttribute('aria-label', 'Player pages');
      nav.hidden = true;
      var prev = document.createElement('button');
      prev.type = 'button';
      prev.className = 'ar-pager-btn';
      prev.setAttribute('data-step', 'prev');
      prev.textContent = 'Previous';
      var label = document.createElement('span');
      label.className = 'ar-pager-label';
      var next = document.createElement('button');
      next.type = 'button';
      next.className = 'ar-pager-btn';
      next.setAttribute('data-step', 'next');
      next.textContent = 'Next';
      nav.appendChild(prev);
      nav.appendChild(label);
      nav.appendChild(next);
      nav.addEventListener('click', function (ev) {
        var btn = ev.target.closest('[data-step]');
        if (!btn || btn.disabled) return;
        var key = p.getAttribute('data-panel');
        var cur = pageState[key] || 0;
        pageState[key] = btn.getAttribute('data-step') === 'next' ? cur + 1 : cur - 1;
        applyPaging(key, true);
      });
      return nav;
    }
    var list = p.querySelector('.ar-list');
    var top = make();
    list.parentNode.insertBefore(top, list);
    list.parentNode.insertBefore(make(), list.nextSibling);
  }

  function noun(n) {
    return n === 1 ? 'player' : 'players';
  }

  function refreshTierCounts(name) {
    var key = name === 'pool' ? 'pool' : resolveName(name);
    var p = panel(key);
    if (!p) return;
    var counts = { '': 0 };
    var matched = { '': 0 };
    p.querySelectorAll('.ar-card').forEach(function (row) {
      counts[''] += 1;
      if (!row.hidden) matched[''] += 1;
      var tid = String(row.getAttribute('data-tier-id') || '');
      if (!tid) return;
      counts[tid] = (counts[tid] || 0) + 1;
      if (!row.hidden) matched[tid] = (matched[tid] || 0) + 1;
    });
    var wrap = document.querySelector('[data-tier-filters="' + key + '"]');
    if (wrap) {
      wrap.querySelectorAll('.ar-tier-chip').forEach(function (btn) {
        var tid = String(btn.getAttribute('data-tier-id') || '');
        var n = counts[tid] || 0;
        var slot = btn.querySelector('.ar-tier-count');
        if (slot) slot.textContent = String(n);
        var nameEl = btn.querySelector('.ar-tier-name');
        var label = nameEl ? nameEl.textContent : 'Tier';
        btn.setAttribute('aria-label', label + ', ' + n + ' ' + noun(n));
      });
    }
    var summary = document.querySelector('[data-tier-summary="' + key + '"]');
    if (!summary) return;
    var active = wrap ? Array.prototype.filter.call(
      wrap.querySelectorAll('.ar-tier-chip.is-active'),
      function (btn) { return String(btn.getAttribute('data-tier-id') || '') !== ''; }
    ) : [];
    if (!active.length) {
      var shownAll = matched[''] || 0;
      var totalAll = counts[''] || 0;
      summary.textContent = shownAll === totalAll
        ? (shownAll + ' ' + noun(shownAll))
        : (shownAll + ' of ' + totalAll + ' ' + noun(totalAll));
      return;
    }
    var names = [];
    var total = 0;
    var shown = 0;
    active.forEach(function (btn) {
      var tid = String(btn.getAttribute('data-tier-id') || '');
      var nameEl = btn.querySelector('.ar-tier-name');
      names.push(nameEl ? nameEl.textContent : 'Tier');
      total += counts[tid] || 0;
      shown += matched[tid] || 0;
    });
    summary.textContent = shown === total
      ? (shown + ' ' + noun(shown) + ' in ' + names.join(', '))
      : (shown + ' of ' + total + ' ' + noun(total) + ' in ' + names.join(', '));
  }

  function setSelectAll(btn, label, count) {
    var name = btn.querySelector('.ar-select-all-label');
    var num = btn.querySelector('.ar-select-all-count');
    if (!name || !num) {
      btn.textContent = count ? (label + ' ' + count) : label;
      return;
    }
    name.textContent = label;
    num.hidden = !count;
    if (count) num.textContent = String(count);
  }

  function updateSelectAllLabel() {
    document.querySelectorAll('[data-select-all]').forEach(function (btn) {
      var p = panel(btn.getAttribute('data-select-all'));
      if (!p) return;
      var rows = p.querySelectorAll('.ar-card:not([hidden])');
      var allOn = rows.length && Array.prototype.every.call(rows, function (row) {
        var cb = row.querySelector('input[type="checkbox"]');
        return cb && cb.checked;
      });
      if (!rows.length) {
        btn.classList.remove('is-clear');
        setSelectAll(btn, 'Select all', 0);
      } else if (allOn) {
        btn.classList.add('is-clear');
        setSelectAll(btn, 'Clear all', rows.length);
      } else {
        btn.classList.remove('is-clear');
        setSelectAll(btn, 'Select all', rows.length);
      }
    });
  }

  function applyPaging(name, scroll) {
    var p = panel(name);
    if (!p) return;
    ensurePager(p);
    var key = p.getAttribute('data-panel');
    var matches = [];
    p.querySelectorAll('.ar-card').forEach(function (row) {
      if (!row.hidden) matches.push(row);
    });
    var size = pageSize();
    var pages = Math.max(1, Math.ceil(matches.length / size) || 1);
    var page = pageState[key] || 0;
    if (page > pages - 1) page = pages - 1;
    if (page < 0) page = 0;
    pageState[key] = page;
    var start = page * size;
    matches.forEach(function (row, i) {
      row.classList.toggle('is-offpage', i < start || i >= start + size);
    });
    var from = matches.length ? (start + 1) : 0;
    var to = Math.min(start + size, matches.length);
    p.querySelectorAll('.ar-pager').forEach(function (nav) {
      nav.hidden = matches.length <= size;
      var label = nav.querySelector('.ar-pager-label');
      if (label) label.textContent = matches.length ? (from + '–' + to + ' of ' + matches.length) : '';
      var prev = nav.querySelector('[data-step="prev"]');
      var next = nav.querySelector('[data-step="next"]');
      if (prev) prev.disabled = page <= 0;
      if (next) next.disabled = page >= pages - 1;
    });
    updateSelectAllLabel();
    if (scroll) {
      var top = p.querySelector('.ar-pager');
      if (top && !top.hidden) top.scrollIntoView({ block: 'start' });
    }
  }

  function applyPanelFilters(name, resetPage) {
    var key = name === 'pool' ? 'pool' : resolveName(name);
    var p = panel(key);
    if (!p) return;
    var input = document.querySelector('[data-search="' + key + '"]');
    var q = ((input && input.value) || '').trim().toLowerCase();
    if (q.charAt(0) === '#') q = q.slice(1).trim();
    var tierIds = activeTier(key);
    var allMode = !tierIds.length;
    var any = false;
    var cards = p.querySelectorAll('.ar-card');
    cards.forEach(function (row) {
      var hay = (
        (row.getAttribute('data-search') || '') + ' ' +
        (row.getAttribute('data-name') || '') + ' ' +
        (row.getAttribute('data-sl-no') || '') + ' ' +
        (row.getAttribute('data-tier-name') || '')
      ).toLowerCase();
      var matchSearch = !q || hay.indexOf(q) !== -1;
      var rowTier = String(row.getAttribute('data-tier-id') || '');
      var matchTier = allMode || (rowTier && tierIds.indexOf(rowTier) !== -1);
      var show = matchSearch && matchTier;
      row.hidden = !show;
      if (show) any = true;
    });
    var nomatch = p.querySelector('.ar-nomatch');
    if (nomatch) nomatch.hidden = any || !cards.length;
    if (resetPage) pageState[p.getAttribute('data-panel')] = 0;
    applyPaging(p.getAttribute('data-panel'));
    refreshTierCounts(key);
  }

  document.querySelectorAll('[data-search]').forEach(function (input) {
    input.addEventListener('input', function () {
      applyPanelFilters(input.getAttribute('data-search'), true);
      renderSelection();
    });
    input.addEventListener('focus', function () { shell.classList.add('is-searching'); fitBar(); });
    input.addEventListener('blur', function () { shell.classList.remove('is-searching'); fitBar(); });
  });

  document.querySelectorAll('[data-tier-filters]').forEach(function (wrap) {
    var name = wrap.getAttribute('data-tier-filters');
    wrap.querySelectorAll('.ar-tier-chip').forEach(function (btn) {
      btn.addEventListener('click', function () {
        var tid = String(btn.getAttribute('data-tier-id') || '');
        if (!tid) {
          wrap.querySelectorAll('.ar-tier-chip').forEach(function (b) {
            b.classList.toggle('is-active', !String(b.getAttribute('data-tier-id') || ''));
          });
        } else {
          var allBtn = wrap.querySelector('.ar-tier-chip[data-tier-id=""]');
          if (allBtn) allBtn.classList.remove('is-active');
          btn.classList.toggle('is-active');
          if (!wrap.querySelector('.ar-tier-chip.is-active[data-tier-id]:not([data-tier-id=""])')) {
            if (allBtn) allBtn.classList.add('is-active');
          }
        }
        applyPanelFilters(name, true);
        renderSelection();
      });
    });
  });

  function selectedIds(name) {
    var p = panel(name);
    if (!p) return [];
    return Array.prototype.map.call(
      p.querySelectorAll('.ar-card:not([hidden]) input[type="checkbox"]:checked'),
      function (el) { return parseInt(el.value, 10); }
    ).filter(Boolean);
  }
  function allVisibleIds(name) {
    var p = panel(name);
    if (!p) return [];
    return Array.prototype.map.call(
      p.querySelectorAll('.ar-card:not([hidden]) input[type="checkbox"]'),
      function (el) { return parseInt(el.value, 10); }
    ).filter(Boolean);
  }
  function syncSelected(row) {
    var cb = row.querySelector('input[type="checkbox"]');
    row.classList.toggle('is-selected', !!(cb && cb.checked));
  }
  function renderSelection() {
    var name = poolName();
    var ids = selectedIds(name);
    var countEl = document.querySelector('.ar-count');
    if (countEl) {
      countEl.hidden = !!ids.length;
      countEl.textContent = ids.length === 1 ? '1 selected' : (ids.length + ' selected');
    }
    var send = document.querySelector('.ar-send');
    if (send) {
      send.disabled = !ids.length;
      send.textContent = !ids.length
        ? 'Select players'
        : (ids.length === 1 ? 'Call 1 player' : ('Call ' + ids.length + ' players'));
    }
    var sendAll = document.querySelector('.ar-send-all');
    if (sendAll) sendAll.textContent = 'Call all ' + (name === 'unsold' ? 'Unsold' : 'Draft');
    var picks = document.querySelector('.ar-tier-picks');
    if (picks) {
      while (picks.firstChild) picks.removeChild(picks.firstChild);
      var groups = {};
      var order = [];
      ids.forEach(function (id) {
        var card = document.querySelector('.ar-panel[data-panel="' + name + '"] .ar-card[data-id="' + id + '"]');
        var key = (card && card.getAttribute('data-tier-id')) || '';
        if (!groups[key]) {
          var chip = key
            ? document.querySelector('[data-tier-filters="pool"] .ar-tier-chip[data-tier-id="' + key + '"] .ar-tier-name')
            : null;
          var raw = (card && card.getAttribute('data-tier-name')) || '';
          groups[key] = { count: 0, label: chip ? chip.textContent : (raw ? raw.toUpperCase() : 'Other') };
          order.push(key);
        }
        groups[key].count += 1;
      });
      var chipOrder = [];
      document.querySelectorAll('[data-tier-filters="pool"] .ar-tier-chip').forEach(function (btn) {
        var tid = String(btn.getAttribute('data-tier-id') || '');
        if (tid) chipOrder.push(tid);
      });
      order.sort(function (a, b) {
        var ia = chipOrder.indexOf(a);
        var ib = chipOrder.indexOf(b);
        return (ia < 0 ? 999 : ia) - (ib < 0 ? 999 : ib);
      });
      order.forEach(function (key) {
        var box = document.createElement('div');
        box.className = 'ar-tier-pick';
        var label = document.createElement('span');
        label.className = 'ar-tier-pick-name';
        label.textContent = groups[key].label;
        var count = document.createElement('span');
        count.className = 'ar-tier-pick-count';
        count.textContent = String(groups[key].count);
        box.appendChild(label);
        box.appendChild(count);
        picks.appendChild(box);
      });
      picks.hidden = !order.length;
    }
    fitBar();
    updateSelectAllLabel();
  }

  document.querySelectorAll('.ar-card').forEach(function (row) {
    var cb = row.querySelector('input[type="checkbox"]');
    if (!cb) return;
    cb.addEventListener('change', function () { syncSelected(row); renderSelection(); });
    row.addEventListener('click', function (ev) {
      if (ev.target.closest('button') || ev.target.closest('input')) return;
      cb.checked = !cb.checked;
      syncSelected(row);
      renderSelection();
    });
    syncSelected(row);
  });

  document.querySelectorAll('[data-pool-pick]').forEach(function (btn) {
    btn.addEventListener('click', function () {
      var name = btn.getAttribute('data-pool-pick');
      shell.setAttribute('data-pool', name);
      document.querySelectorAll('[data-pool-pick]').forEach(function (other) {
        var on = other.getAttribute('data-pool-pick') === name;
        other.classList.toggle('is-on', on);
        other.setAttribute('aria-pressed', on ? 'true' : 'false');
      });
      document.querySelectorAll('.ar-panel[data-panel="draft"], .ar-panel[data-panel="unsold"]').forEach(function (p) {
        p.hidden = p.getAttribute('data-panel') !== name;
      });
      applyPanelFilters('pool');
      renderSelection();
    });
  });

  document.querySelectorAll('[data-select-all]').forEach(function (btn) {
    btn.addEventListener('click', function () {
      var name = btn.getAttribute('data-select-all');
      var p = panel(name);
      if (!p) return;
      var rows = p.querySelectorAll('.ar-card:not([hidden])');
      var boxes = [];
      rows.forEach(function (row) {
        var cb = row.querySelector('input[type="checkbox"]');
        if (cb) boxes.push(row);
      });
      if (!boxes.length) {
        toast('No players to select');
        return;
      }
      var allOn = boxes.every(function (row) {
        return row.querySelector('input[type="checkbox"]').checked;
      });
      boxes.forEach(function (row) {
        row.querySelector('input[type="checkbox"]').checked = !allOn;
        syncSelected(row);
      });
      renderSelection();
    });
  });

  function fitLine(el, max, min) {
    if (!el) return;
    var size = max;
    el.style.fontSize = size + 'px';
    var guard = 0;
    while (el.scrollWidth > el.clientWidth + 1 && size > min && guard < 40) {
      size -= 0.5;
      el.style.fontSize = size.toFixed(1) + 'px';
      guard += 1;
    }
  }
  function fitTitle() {
    var wide = window.matchMedia('(min-width: 900px)').matches;
    var mid = window.matchMedia('(min-width: 640px)').matches;
    fitLine(document.querySelector('.ar-title'), wide ? 23 : (mid ? 18 : 15), 8);
    fitLine(document.querySelector('.ar-sub'), wide ? 15 : (mid ? 13 : 11), 8);
  }
  function fitLoader() {
    var loader = document.getElementById('ar-loader');
    if (!loader || loader.hidden) return;
    var wide = window.matchMedia('(min-width: 900px)').matches;
    var mid = window.matchMedia('(min-width: 640px)').matches;
    fitLine(document.getElementById('ar-loader-title'), wide ? 28 : (mid ? 22 : 18), 10);
    fitLine(document.querySelector('.ar-loader-sub'), wide ? 18 : 16, 11);
  }
  function fitBar() {
    var rail = document.querySelector('.ar-rail');
    if (!rail) return;
    var narrow = window.matchMedia('(max-width: 899px)').matches;
    var searching = shell.classList.contains('is-searching');
    if (narrow && !searching) {
      var height = rail.offsetHeight || 0;
      shell.style.paddingBottom = (height + 12) + 'px';
      shell.style.setProperty('--ar-dock', (height + 16) + 'px');
    } else {
      shell.style.paddingBottom = '';
      shell.style.setProperty('--ar-dock', '24px');
    }
  }
  window.addEventListener('resize', function () {
    fitBar();
    fitTitle();
    fitLoader();
    document.querySelectorAll('.ar-panel').forEach(function (p) {
      applyPaging(p.getAttribute('data-panel'));
    });
  });
  var chooser = document.getElementById('ar-chooser');
  if (chooser) {
    shell.classList.toggle('is-choosing', chooser.open);
    chooser.addEventListener('toggle', function () {
      shell.classList.toggle('is-choosing', chooser.open);
      fitBar();
    });
  }

  function doSubmitOpen(ids) {
    busy = true;
    shell.classList.add('ar-busy');
    var loader = document.getElementById('ar-loader');
    var loaderTitle = document.getElementById('ar-loader-title');
    if (loaderTitle) {
      loaderTitle.textContent = ids.length === 1
        ? 'Calling the player into the auction'
        : 'Calling players into the auction';
    }
    if (loader) loader.hidden = false;
    fitLoader();
    form.setAttribute('action', openUrl);
    form.setAttribute('method', 'POST');
    idsInput.name = 'player_ids';
    idsInput.value = ids.join(',');
    form.submit();
  }
  function submitOpen(ids, opts) {
    if (busy) return;
    if (!ids || !ids.length) {
      toast('Select at least one player');
      return;
    }
    var count = ids.length;
    var label = count === 1 ? 'this player' : ('<strong>' + count + '</strong> players');
    arConfirm({
      icon: '🎯',
      title: opts && opts.title ? opts.title : 'Call these players into the auction?',
      message: (opts && opts.message) ||
        ('Call ' + label + ' into the live auction and resume the presentation?'),
      confirmLabel: count === 1 ? 'Call player' : ('Call ' + count + ' players'),
      danger: false,
    }).then(function (ok) {
      if (ok) doSubmitOpen(ids);
    });
  }
  function submitComplete() {
    if (busy) return;
    arConfirm({
      icon: '🏁',
      title: 'Declare auction complete?',
      message: 'This shows the <strong>Thank You</strong> screen with the final squads. Draft and Unsold players can still be opened later from the backend.',
      confirmLabel: 'Yes, complete',
      danger: true,
    }).then(function (ok) {
      if (!ok) return;
      busy = true;
      shell.classList.add('ar-busy');
      form.setAttribute('action', completeUrl);
      form.setAttribute('method', 'POST');
      idsInput.name = 'player_ids';
      idsInput.value = '';
      form.submit();
    });
  }
  function submitMarkUnsold() {
    if (busy || !markUnsoldUrl) return;
    arConfirm({
      icon: '📭',
      title: 'Mark remaining as unsold?',
      message: 'Every player still <strong>In Auction</strong> moves to <strong>Unsold</strong>. The squads are already full, so they cannot be sold.',
      confirmLabel: 'Mark all unsold',
      danger: true,
    }).then(function (ok) {
      if (!ok) return;
      busy = true;
      shell.classList.add('ar-busy');
      toast('Marking remaining players as unsold…');
      form.setAttribute('action', markUnsoldUrl);
      form.setAttribute('method', 'POST');
      idsInput.name = 'player_ids';
      idsInput.value = '';
      form.submit();
    });
  }

  document.querySelectorAll('[data-open]').forEach(function (btn) {
    btn.addEventListener('click', function () {
      var name = btn.getAttribute('data-open');
      var pool = resolveName(name);
      submitOpen(selectedIds(name), {
        title: pool === 'unsold' ? 'Call these unsold players?' : 'Call these draft players?',
      });
    });
  });
  document.querySelectorAll('[data-open-all]').forEach(function (btn) {
    btn.addEventListener('click', function () {
      var name = btn.getAttribute('data-open-all');
      var pool = resolveName(name);
      var ids = allVisibleIds(name);
      if (!ids.length) {
        toast('No players to call');
        return;
      }
      submitOpen(ids, {
        title: pool === 'unsold' ? 'Call all unsold players?' : 'Call all draft players?',
        message: 'Call all <strong>' + ids.length + '</strong> ' + pool +
          ' players into the live auction and resume the presentation?',
      });
    });
  });
  document.querySelectorAll('[data-open-one]').forEach(function (btn) {
    btn.addEventListener('click', function (ev) {
      ev.preventDefault();
      ev.stopPropagation();
      var id = parseInt(btn.getAttribute('data-open-one'), 10);
      if (!id) return;
      var row = btn.closest('.ar-card');
      var pname = row ? (row.getAttribute('data-label') || '') : '';
      submitOpen([id], {
        title: 'Call this player into the auction?',
        message: 'Call <strong>' + esc(pname || 'this player') +
          '</strong> into the live auction and resume the presentation?',
      });
    });
  });
  document.querySelectorAll('.ar-complete-btn').forEach(function (btn) {
    btn.addEventListener('click', submitComplete);
  });
  var markUnsoldBtn = document.getElementById('ar-mark-unsold-btn');
  if (markUnsoldBtn) markUnsoldBtn.addEventListener('click', submitMarkUnsold);

  document.querySelectorAll('.ar-panel').forEach(function (p) {
    applyPaging(p.getAttribute('data-panel'));
  });
  refreshTierCounts('pool');
  refreshTierCounts('auction');
  renderSelection();
  fitBar();
  fitTitle();
})();
